await api.waTyping(chatId, caption.length + 20, type === 'audio');
const opts = Object.assign({ type, createChat: String(args.allow_new) === 'true' }, api.waQuote(args));
if (caption && type !== 'audio' && type !== 'sticker') opts.caption = caption;
if (args.filename) opts.filename = String(args.filename);
if (type === 'audio' && String(args.voice) === 'true') opts.isPtt = true;
const r = await WPP.chat.sendFileMessage(chatId, file, opts);
